package com.manjul.aikeyboard.fork.themes

import androidx.annotation.StringRes
import com.manjul.aikeyboard.R

/**
 * The keyboard click choice (S4 Task 10), stored as [wire] in `FeatureSettings.keySound`. [SYSTEM] keeps the
 * upstream platform click (`AudioManager.playSoundEffect`); [OFF] is silent; the rest play a bundled sound
 * from `res/raw` (generated by `:tools:themegen`) through [KeySoundPlayer].
 */
enum class KeySound(val wire: String, val rawRes: Int?, @param:StringRes val label: Int) {
    OFF("off", null, R.string.themes__key_sound_off),
    SYSTEM("system", null, R.string.themes__key_sound_system),
    SOFT("soft", R.raw.key_soft, R.string.themes__key_sound_soft),
    CRISP("crisp", R.raw.key_crisp, R.string.themes__key_sound_crisp),
    WOOD("wood", R.raw.key_wood, R.string.themes__key_sound_wood),
    POP("pop", R.raw.key_pop, R.string.themes__key_sound_pop),
    ;

    companion object {
        /** An unknown or empty value plays like [SYSTEM], the upstream behaviour. */
        fun fromWire(wire: String): KeySound = entries.firstOrNull { it.wire == wire } ?: SYSTEM
    }
}
